#pragma once

#include <cstddef>
#include <cstdint>
#include <memory>
#include <span>

namespace dsp56300::detail {
class ExecutableArena;
struct Cpu;
struct NativeContext;
}

namespace dsp56300::test::native {
// Test-only direct execution of the identical helper-free generated bytes.
class Direct {
public:
  explicit Direct(std::span<const std::uint8_t> code);
  ~Direct();
  Direct(const Direct &) = delete;
  Direct &operator=(const Direct &) = delete;
  Direct(Direct &&) = delete;
  Direct &operator=(Direct &&) = delete;
  [[nodiscard]] std::uint32_t enter(detail::Cpu &cpu,
                                    detail::NativeContext &context) const noexcept;

private:
#if defined(__aarch64__)
  std::unique_ptr<detail::ExecutableArena> arena_;
  const void *entry_ = nullptr;
#else
  void *mapping_ = nullptr;
  std::size_t size_ = 0;
#endif
};
} // namespace dsp56300::test::native
